CREATE OR REPLACE VIEW CMS.DRUG_EVENT_CMS_DDPS_RETURN_POST2025_VW AS
SELECT
    SUBSTR(HEADER_APPENDED_RECORD, 1, 3)                                                                      AS RECORD_ID,
    TRY_TO_NUMBER(SUBSTR(HEADER_APPENDED_RECORD, 4, 7))                                                       AS SEQUENCE_NO,
    SUBSTR(HEADER_APPENDED_RECORD, 11, 40)                                                                    AS CLAIM_CONTROL_NUMBER,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 51, 20))                                                              AS HEALTH_INS_CLAIM_NUMBER,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 71, 20))                                                              AS CARDHOLDER_ID,
    TRY_TO_DATE(NULLIF(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 91, 8)),''),'YYYYMMDD')                            AS DATE_OF_BIRTH_DOB,
    TRY_TO_NUMBER(SUBSTR(HEADER_APPENDED_RECORD, 99, 1))                                                      AS PATIENT_GENDER_CODE,
    TRY_TO_DATE(NULLIF(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 100, 8)),''),'YYYYMMDD')                           AS DATE_OF_SERVICE,
    TRY_TO_DATE(NULLIF(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 108, 8)),''),'YYYYMMDD')                           AS PAID_DATE,
    TRY_TO_NUMBER(SUBSTR(HEADER_APPENDED_RECORD, 116, 12))                                                    AS PRESCRIPTION_SERVICE_REF_NO,
    NULL                                                                                                      AS FILLER,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 128, 40))                                                             AS PRODUCT_SERVICE_ID,
    SUBSTR(HEADER_APPENDED_RECORD, 198, 2)                                                                    AS SERVICE_PROVIDER_ID_QUALIFIER,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 200, 15))                                                             AS SERVICE_PROVIDER_ID,
    TRY_TO_NUMBER(SUBSTR(HEADER_APPENDED_RECORD, 215, 2))                                                     AS FILL_NUMBER,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 217, 1))                                                              AS DISPENSING_STATUS,
    TRY_TO_NUMBER(SUBSTR(HEADER_APPENDED_RECORD, 218, 1))                                                     AS COMPOUND_CODE,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 219, 1))                                                              AS DISP_AS_WRITTEN_PROD_SEL_CODE,
    TRY_TO_NUMBER(SUBSTR(HEADER_APPENDED_RECORD, 230, 10))                                                    AS QUANTITY_DISPENSED,
    TRY_TO_NUMBER(SUBSTR(HEADER_APPENDED_RECORD, 243, 3))                                                     AS DAYS_SUPPLY,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 246, 2))                                                              AS PRESCRIBER_ID_QUALIFIER,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 248, 35))                                                             AS PRESCRIBER_ID,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 283, 1))                                                              AS DRUG_COVERAGE_STATUS_CODE,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 284, 1))                                                              AS ADJUSTMENT_DELETION_CODE,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 285, 1))                                                              AS NON_STANDARD_FORMAT_CODE,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 286, 1))                                                              AS PRICING_EXCEPTION_CODE,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 315, 1))                                                              AS CATASTROPHIC_COVERAGE_CODE,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 316, 11)))                                          AS INGREDIENT_COST_PAID,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 327, 11)))                                          AS DISPENSING_FEE_PAID,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 338, 11)))                                          AS TOTAL_AMT_ATTRIB_TO_SALES_TAX,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 437, 11)))                                          AS GROSS_DRUG_COST_BELOW_POCKET,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 448, 11)))                                          AS GROSS_DRUG_COST_ABOVE_POCKET,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 459, 11)))                                          AS PATIENT_PAY_AMOUNT,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 470, 11)))                                          AS OTHER_TROOP_AMOUNT, 
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 481, 11)))                                          AS LOW_INCOME_COST_SHAR_SUB_AMT,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 492, 11)))                                          AS PAT_LIAB_RED_OTHER_PAYER_AMT,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 503, 11)))                                          AS COVERED_PLAN_PAID_AMOUNT,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 514, 11)))                                          AS NON_COVERED_PLAN_PAID_AMOUNT,
    NULL                                                                                                      AS SUBMITTING_CONTRACT,
    NULL                                                                                                      AS CORRECTED_HICN,
    TRY_TO_NUMBER(SUBSTR(HEADER_APPENDED_RECORD, 946, 2))                                                     AS ERROR_COUNT,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 948, 3))                                                              AS ERROR_1,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 951, 3))                                                              AS ERROR_2,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 954, 3))                                                              AS ERROR_3,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 957, 3))                                                              AS ERROR_4,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 960, 3))                                                              AS ERROR_5,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 963, 3))                                                              AS ERROR_6,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 966, 3))                                                              AS ERROR_7,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 969, 3))                                                              AS ERROR_8,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 972, 3))                                                              AS ERROR_9,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 975, 3))                                                              AS ERROR_10, 
    NULL                                                                                                      AS FILLER3,
    FILE_LAST_MODIFIED_DATETIME                                                                               AS INSERT_DATETIME,
    NULL                                                                                                      AS CONTRACT_OF_RECORD,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 1001, 3))                                                             AS RECORD_ID_BHD,
    TRY_TO_NUMBER(SUBSTR(HEADER_APPENDED_RECORD, 1004, 7))                                                    AS SEQUENCE_NUMBER_BHD,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 1011, 5))                                                             AS CONTRACT_NUMBER_BHD,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 1016, 3))                                                             AS PBP_ID_BHD,
    TRY_TO_DATE(NULLIF(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 1019, 8)),''),'YYYYMMDD')                          AS DDPS_SYSTEM_DATE_BHD,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 1027, 6))                                                             AS DDPS_SYSTEM_TIME_BHD,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 1033, 5))                                                             AS DDPS_REPORT_ID_BHD,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 1038, 475))                                                           AS FILLER_BHD,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 896, 2))                                                              AS ALT_SERV_PROVIDER_ID_QUALIFIER,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 898, 15))                                                             AS ALT_SERV_PROVIDER_ID,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 913, 5))                                                              AS ORIGINAL_SUBMITTING_CONTRACT,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 938, 5))                                                              AS P2P_CONTRACT_OF_RECORD,
    NULL                                                                                                      AS P2P_PBP_OF_RECORD,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 349, 11)))                                          AS ESTIMATED_REBATE_AT_POS,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 371, 11)))                                          AS VACCINE_ADMINISTRATION_FEE,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 664, 1))                                                              AS PRESCRIP_ORIGIN_CODE,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 978, 3))                                                              AS EXCLUSION_REASON_CODE,
    NULL                                                                                                      AS FILLER2,
    TRY_TO_DATE(NULLIF(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 665, 8)),''),'YYYYMMDD')                           AS DATE_ORIG_CLAIM_RECEIVED,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 673, 26))                                                             AS CLAIM_ADJUD_BEGAN_TIMESTAMP,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 624, 11)))                                          AS TOTAL_COV_COST_ACCUM_TGCDC,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 637, 11)))                                          AS OUT_OF_POCKET_ACCUM_TROOP,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 699, 1))                                                              AS BRAND_GENERIC_CODE,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 662, 1))                                                              AS BEGINNING_BENEFIT_PHASE,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 663, 1))                                                              AS ENDING_BENEFIT_PHASE,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 547, 11)))                                          AS REPORTED_GAP_DISCOUNT,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 701, 1))                                                              AS FORMULARY_CODE,
    TRIM(SUBSTR(HEADER_APPENDED_RECORD, 700, 1))                                                              AS TIER,
    NULL                                                                                                      AS NON_PECOS_NPI_IND,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 819, 11)))                                          AS CMS_CALC_SELECTED_DRUG_SUBSIDY,
    CMS.FXN_OVERPUNCH(TRIM(SUBSTR(HEADER_APPENDED_RECORD, 830, 11)))                                          AS CMS_CALC_GAP_DISCOUNT,
    NULL                                                                                                      AS FILLER4,
    FILENAME                                                                                                  AS FILENAME,
    SUBSTR(HEADER_APPENDED_RECORD, 702, 2)                                                                    AS PHARM_SERV_TYPE,
    SUBSTR(HEADER_APPENDED_RECORD, 704, 2)                                                                    AS PATIENT_RES,
    NULL                                                                                                      AS SUB_CLAR_CODE,
    SUBSTR(HEADER_APPENDED_RECORD, 733, 1)                                                                    AS ADJUST_REASON_CD_QUAL,
    SUBSTR(HEADER_APPENDED_RECORD, 734, 12)                                                                   AS ADJUST_REASON_CD,
    NULL                                                                                                      AS TYPE_OF_FILL,
    NULL                                                                                                      AS MED_BENE_INDEN_NUMBER,
    SUBSTR(HEADER_APPENDED_RECORD, 918, 20)                                                                   AS CORRECTED_MBI,
    CMS.FXN_OVERPUNCH(SUBSTR(HEADER_APPENDED_RECORD, 525, 11))                                                AS SELECTED_DRUG_SUBSIDY,
    TRY_TO_NUMBER(SUBSTR(HEADER_APPENDED_RECORD, 220, 10))                                                    AS ORIGINALLY_PRESCRIBED_QUANTITY,
    SUBSTR(HEADER_APPENDED_RECORD, 287, 2)                                                                    AS PART_D_MODEL_INDICATOR,
    CMS.FXN_OVERPUNCH(SUBSTR(HEADER_APPENDED_RECORD, 360, 11))                                                AS PHARMACY_PRICE_CONCESSIONS_POS,
    CMS.FXN_OVERPUNCH(SUBSTR(HEADER_APPENDED_RECORD, 536, 11))                                                AS REPORTED_MANUFACTURER_DISCOUNT,
    CASE 
         WHEN TRIM(SUBSTR(HEADER_APPENDED_RECORD, 650, 11)) = '' THEN 0
         WHEN SUBSTR(HEADER_APPENDED_RECORD, 650, 11) = NULL THEN 0
         ELSE CMS.FXN_OVERPUNCH(SUBSTR(HEADER_APPENDED_RECORD, 650, 11)) 
    END                                                                                                       AS DEDUCTIBLE_ACCUMULATOR,
    SUBSTR(HEADER_APPENDED_RECORD, 661, 1)                                                                    AS OTHER_TROOP_AMOUNT_IND,
    SUBSTR(HEADER_APPENDED_RECORD, 706, 2)                                                                    AS SUBMISSION_TYPE_CODE_1,
    SUBSTR(HEADER_APPENDED_RECORD, 708, 2)                                                                    AS SUBMISSION_TYPE_CODE_2,
    SUBSTR(HEADER_APPENDED_RECORD, 710, 2)                                                                    AS SUBMISSION_TYPE_CODE_3,
    SUBSTR(HEADER_APPENDED_RECORD, 712, 2)                                                                    AS SUBMISSION_TYPE_CODE_4,
    SUBSTR(HEADER_APPENDED_RECORD, 714, 2)                                                                    AS SUBMISSION_TYPE_CODE_5,
    SUBSTR(HEADER_APPENDED_RECORD, 716, 3)                                                                    AS SUBMISSION_CLARIFICATION_CODE_1,
    SUBSTR(HEADER_APPENDED_RECORD, 719, 3)                                                                    AS SUBMISSION_CLARIFICATION_CODE_2,
    SUBSTR(HEADER_APPENDED_RECORD, 722, 3)                                                                    AS SUBMISSION_CLARIFICATION_CODE_3,
    SUBSTR(HEADER_APPENDED_RECORD, 725, 3)                                                                    AS SUBMISSION_CLARIFICATION_CODE_4,
    SUBSTR(HEADER_APPENDED_RECORD, 728, 3)                                                                    AS SUBMISSION_CLARIFICATION_CODE_5,
    SUBSTR(HEADER_APPENDED_RECORD, 731, 2)                                                                    AS LTPAC_DISPENSE_FREQUENCY,
    CMS.FXN_OVERPUNCH(SUBSTR(HEADER_APPENDED_RECORD, 841, 11))                                                AS CMS_CALC_MANUF_DISCOUNT,
    SUBSTR(HEADER_APPENDED_RECORD, 852, 2)                                                                    AS DISCOUNT_PRCT_MANUF_DRUGS,
    SUBSTR(HEADER_APPENDED_RECORD, 854, 2)                                                                    AS DISCOUNT_PRCT_MANUF_LIS_BENE,
    SUBSTR(HEADER_APPENDED_RECORD, 856, 1)                                                                    AS DRUG_STATUS_IND,
    SUBSTR(HEADER_APPENDED_RECORD, 289, 1)                                                                    AS MEDICARE_PRESCRIP_PMT_PLAN_IND
FROM CMS.DRUG_EVENT_DDPS_RETURN_STAGE
WHERE SUBSTR(HEADER_APPENDED_RECORD, 1,3) NOT LIKE 'HDR%'
AND SUBSTR(HEADER_APPENDED_RECORD, 1,3) NOT LIKE 'BHD%'
AND SUBSTR(HEADER_APPENDED_RECORD, 1,3) NOT LIKE 'BTR%'
AND SUBSTR(HEADER_APPENDED_RECORD, 1,3) NOT LIKE 'TLR%'
AND SUBSTR(HEADER_APPENDED_RECORD, 1,3) NOT LIKE 'DET%';